import * as React from 'react'
import {useCallback, useMemo} from 'react'

import {EntityProvider} from '../../../../contexts/entity'
import type {BuildTypeId, PipelineId} from '../../../../types'
import {deduplicate, toGroups} from '../../../../utils/array'
import Grid from '../../Grid/Grid'
import SequenceLoader from '../../SequenceLoader/SequenceLoader'
import Visible from '../../Visible/Visible'
import ShowAllBuildTypes from '../ShowAllBuildTypes/ShowAllBuildTypes'

import type {Props} from './BuildTypes.types'
import {NestedBuildTypes} from './BuildTypesContext'

import styles from './BuildTypes.module.css'

type BuildSortedIds = {
  pipelineId?: PipelineId
  buildTypeId?: BuildTypeId
}

const GROUP_SIZE = 10
export default function BuildTypes({
  overviewBuildTypeIds,
  overviewPipelineIds,
  buildTypeIds,
  pipelineIds,
  onlyFavorites = false,
  hasFavorites,
  archivedProject,
  gridClassName,
}: Props) {
  const [showAll, setShowAll] = React.useReducer(() => true, false)
  const showOnlyFavorites = onlyFavorites || (hasFavorites && !showAll)
  const mergedBuildTypeIds = deduplicate([
    ...overviewBuildTypeIds,
    ...(!showOnlyFavorites ? buildTypeIds : []),
  ])
  const mergedPipelineIds = deduplicate([
    ...overviewPipelineIds,
    ...(!showOnlyFavorites ? pipelineIds : []),
  ])
  const sortedBuildTypeIds: BuildSortedIds[] = [
    ...mergedPipelineIds.map(id => ({pipelineId: id})),
    ...mergedBuildTypeIds.map(id => ({buildTypeId: id})),
  ]
  const groups = toGroups<BuildSortedIds>(GROUP_SIZE, sortedBuildTypeIds)
  const renderBuildTypeLines = useCallback(
    (ids: readonly BuildSortedIds[]) => (
      <>
        <SequenceLoader
          showFirstLoadingItem
          waitForAllLoaded
          className={styles.list}
          itemClassName={styles.item}
        >
          {ids.map(({pipelineId, buildTypeId}) => {
            const key = pipelineId ?? buildTypeId
            const isFavorite = Boolean(
              showOnlyFavorites || (buildTypeId && overviewBuildTypeIds.includes(buildTypeId)),
            )

            return (
              <EntityProvider
                key={key}
                seqKey={key}
                pipelineId={pipelineId}
                buildTypeId={buildTypeId}
              >
                <NestedBuildTypes
                  buildTypeId={buildTypeId}
                  pipelineId={pipelineId}
                  archivedProject={archivedProject}
                  isFavorite={isFavorite}
                />
              </EntityProvider>
            )
          })}
        </SequenceLoader>
      </>
    ),
    [archivedProject, overviewBuildTypeIds, showOnlyFavorites],
  )
  const renderedGroups = useMemo(
    () =>
      groups.map((ids, i) =>
        gridClassName ? (
          // eslint-disable-next-line react/no-array-index-key
          <Grid key={i} className={gridClassName}>
            {renderBuildTypeLines(ids)}
          </Grid>
        ) : (
          // eslint-disable-next-line react/no-array-index-key
          <div key={i} className={styles.container}>
            {renderBuildTypeLines(ids)}
          </div>
        ),
      ),
    [groups, gridClassName, renderBuildTypeLines],
  )
  return (
    <SequenceLoader showFirstLoadingItem withIncrementalRendering>
      {renderedGroups.map((lines, i) => (
        // eslint-disable-next-line react/no-array-index-key
        <Visible key={i} seqKey={String(i)}>
          {() => lines}
        </Visible>
      ))}
      {!onlyFavorites && showOnlyFavorites && buildTypeIds.length > overviewBuildTypeIds.length ? (
        <ShowAllBuildTypes seqKey="showAll" onClick={setShowAll} count={buildTypeIds.length} />
      ) : null}
    </SequenceLoader>
  )
}
