import compose from 'lodash/flowRight'
import * as React from 'react'
import {connect} from 'react-redux'

import type {State} from '../../../../../reducers/types'
import {getFullPath, getOverviewProject, getProject} from '../../../../../selectors'
import type {FullPath, ProjectId, ProjectOrBuildTypeNode} from '../../../../../types'
import {emptyArray} from '../../../../../utils/empty'
import BuildPath from '../../../BuildPath/BuildPath'

import styles from './Subproject.module.css'

type StateProps = {
  path: FullPath
}
type OwnProps = {
  projectId: ProjectId
  level: number
  showFullBreadcrumbs: boolean
}
type Props = StateProps & OwnProps

function SubprojectBreadcrumbs({projectId, path, showFullBreadcrumbs, level}: Props) {
  const nodeType = 'project'
  const projectNode: ProjectOrBuildTypeNode = React.useMemo(
    () => ({
      nodeType,
      id: projectId,
    }),
    [projectId, nodeType],
  )
  const resultPath = React.useMemo(
    () => (showFullBreadcrumbs ? path : path.slice(path.length - level)),
    [level, path, showFullBreadcrumbs],
  )
  return (
    <div className={styles.parentPath}>
      <BuildPath path={resultPath} projectOrBuildTypeNode={projectNode} />
    </div>
  )
}

export default compose(
  React.memo,
  connect((state: State, {projectId, showFullBreadcrumbs}: OwnProps) => {
    const nodeType = 'project'
    const parentId = showFullBreadcrumbs
      ? getOverviewProject(state, projectId)?.parentProjectId
      : getProject(state, projectId)?.parentProjectId
    const path = parentId
      ? getFullPath(
          state,
          {
            nodeType,
            id: parentId,
          },
          showFullBreadcrumbs,
        )
      : emptyArray
    return {
      path,
    }
  }),
)(SubprojectBreadcrumbs)
