import {useMemo} from 'react'

import type {ProjectId} from '../../../types'
import {ROOT_PROJECT_ID} from '../../../types'
import Loader from '../Loader/Loader'
import SequenceLoader, {SequenceLoaderChild} from '../SequenceLoader/SequenceLoader'

import {NestedContent} from './NestedSubprojectsAndBuildTypesContext'
import Subprojects from './Subprojects/Subprojects.container'

type OwnProps = {
  projectId: ProjectId
  parentProjectId?: ProjectId
  hasSubprojectContent?: boolean
  level?: number
  onlyFavorites?: boolean
  projectsReady: boolean
}

const NestedSubprojectsAndBuildTypes = ({
  projectId,
  parentProjectId,
  hasSubprojectContent = false,
  onlyFavorites = false,
  projectsReady,
  level = 0,
}: OwnProps) => {
  const isRoot = projectId === ROOT_PROJECT_ID

  return useMemo(
    () => (
      <SequenceLoader showFirstLoadingItem>
        {!isRoot && hasSubprojectContent ? (
          <SequenceLoaderChild seqKey="self">
            <NestedContent projectId={projectId} />
          </SequenceLoaderChild>
        ) : null}
        <SequenceLoaderChild seqKey="subprojects">
          {projectsReady ? (
            <Subprojects
              level={level}
              projectId={projectId}
              parentProjectId={parentProjectId}
              onlyFavorites={onlyFavorites}
            />
          ) : (
            <Loader />
          )}
        </SequenceLoaderChild>
      </SequenceLoader>
    ),
    [hasSubprojectContent, isRoot, level, onlyFavorites, parentProjectId, projectId, projectsReady],
  )
}

export default NestedSubprojectsAndBuildTypes
