import Tag from '@jetbrains/ring-ui-built/components/tag/tag'
import classNames from 'classnames'

import styles from './OverviewArchivedProjectInfo.module.css'

type Props = {
  className?: string
}

function OverviewArchivedProjectInfo({className}: Props) {
  const classes = classNames(styles.container, className)
  return (
    <Tag readOnly className={classes}>
      {'Archived'}
    </Tag>
  )
}

export default OverviewArchivedProjectInfo
