import Button from '@jetbrains/ring-ui-built/components/button/button'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import plur from 'plur'

import SystemProblemsDialog from '../../../../common/SystemProblemsDialog/SystemProblemsDialog'
import useBooleanState from '../../../PipelinesPages/hooks/useBooleanState'

import type {Props} from './OverviewSystemProblems.types'

import styles from './OverviewSystemProblems.module.css'

function OverviewSystemProblems({
  className,
  systemProblems = [],
  additionalProblems = [],
  buildTypeId,
  projectId,
}: Props) {
  const [isOpenDialog, openDialog, closeDialog] = useBooleanState(false)
  const countProblems = systemProblems.length - 1

  if (!systemProblems.length || buildTypeId == null) {
    return null
  }

  const text = systemProblems[0].title
  return (
    <>
      <div className={classNames(styles.systemProblems, className)}>
        <SvgIcon className={styles.icon} icon="warning" />
        <div className={styles.text} title={text}>
          {text}
        </div>
        {Boolean(countProblems) && (
          <span className={styles.countProblems}>{`(+${countProblems} ${plur(
            'problem',
            countProblems,
          )})`}</span>
        )}
        <Button inline onClick={openDialog} className={styles.showDetails}>
          {'Show details'}
        </Button>
      </div>
      <SystemProblemsDialog
        projectId={projectId}
        systemProblems={systemProblems}
        additionalProblems={additionalProblems}
        isOpenDialog={isOpenDialog}
        closeDialog={closeDialog}
      />
    </>
  )
}

export default OverviewSystemProblems
