import {connect} from 'react-redux'

import type {State} from '../../../../reducers/types'
import {getHasBuildConfigurations, isProjectLoaded} from '../../../../selectors'
import {getOverviewReady} from '../../../../selectors/projectTrees'
import type {ProjectId} from '../../../../types'

import NestedProjectTrendsOrBuildsOverview from './NestedProjectTrendsOrBuildsOverview'

export type OwnProps = {
  projectId: ProjectId
  parentProjectId?: ProjectId
  onlyFavorites?: boolean
}
type StateProps = {
  hasBuilds: boolean
  projectsReady: boolean
}

const mapStateToProps = (
  state: State,
  {projectId, parentProjectId, onlyFavorites}: OwnProps,
): StateProps => ({
  hasBuilds: getHasBuildConfigurations(state, projectId, onlyFavorites),
  projectsReady: onlyFavorites ? getOverviewReady(state) : isProjectLoaded(state, parentProjectId),
})

export default connect(mapStateToProps)(NestedProjectTrendsOrBuildsOverview)
