import type {Context, ReactNode} from 'react'
import {createContext, memo, useContext} from 'react'

import type {BuildTypeId, PipelineId} from '../../../../types'

export const BuildTypesContext: Context<
  (
    archivedProject: boolean,
    isFavorite: boolean,
    buildTypeId?: BuildTypeId,
    pipelineId?: PipelineId,
  ) => ReactNode
> = createContext((_, __, ___): ReactNode => null)
type NestedBuildTypesProps = {
  pipelineId?: PipelineId
  buildTypeId?: BuildTypeId
  archivedProject: boolean
  isFavorite: boolean
}
export const NestedBuildTypes = memo(function NestedBuildTypes({
  buildTypeId,
  pipelineId,
  archivedProject,
  isFavorite,
}: NestedBuildTypesProps) {
  const render = useContext(BuildTypesContext)
  return <>{render(archivedProject, isFavorite, buildTypeId, pipelineId)}</>
})
