import * as React from 'react'

import {
  collapsePipelineRunsSection,
  collapseBuildTypeBuildsSection,
  collapseSubproject,
  expandPipelineRunsSection,
  expandBuildTypeBuildsSection,
  expandSubproject,
} from '../../../actions'
import {useAppDispatch} from '../../../hooks/react-redux'
import type {BuildTypeId, PipelineId, ProjectId} from '../../../types'
import type {PostponedCallbackReturn} from '../../../utils/postponedTask'
import {useResetLoadingState} from '../SequenceLoader/SequenceLoader.hooks'

export function useProjectUnfolderCommonLogics() {
  const dispatch = useAppDispatch()

  const raf = React.useRef<PostponedCallbackReturn[]>([])
  const [processing, setProcessing] = React.useState(false)
  const resetLoadingState = useResetLoadingState()

  const expandEntities = React.useCallback(
    (pipelineIds: PipelineId[], buildTypeIds: BuildTypeId[], projectIds: ProjectId[]) => {
      if (pipelineIds.length) {
        dispatch(expandPipelineRunsSection(pipelineIds))
      }

      if (buildTypeIds.length) {
        dispatch(expandBuildTypeBuildsSection(buildTypeIds))
      }

      if (projectIds.length) {
        dispatch(expandSubproject(projectIds))
      }
    },
    [dispatch],
  )

  const collapseEntities = React.useCallback(
    (pipelineIds: PipelineId[], buildTypeIds: BuildTypeId[], projectIds: ProjectId[]) => {
      if (pipelineIds.length) {
        dispatch(collapsePipelineRunsSection(pipelineIds))
      }

      if (buildTypeIds.length) {
        dispatch(collapseBuildTypeBuildsSection(buildTypeIds))
      }

      if (projectIds.length) {
        dispatch(collapseSubproject(projectIds))
      }
    },
    [dispatch],
  )

  return {
    raf,
    processing,
    setProcessing,
    resetLoadingState,
    expandEntities,
    collapseEntities,
  }
}
