import type {ProjectId} from '../../../../types'
import {UserProperties} from '../../../../utils/userProperties'
import ModeSwitch, {Mode} from '../../../common/ModeSwitch/ModeSwitch'
import BuildProblems from '../../../packages/Problems/BuildProblems/BuildProblems'
import {
  BUILD_PROBLEMS_TAB_LABEL,
  Problems,
  TESTS_TAB_LABEL,
} from '../../../packages/Problems/Problems.types'
import TestProblems from '../../../packages/Problems/TestProblems/TestProblems'

import styles from './ProjectProblemsTab.module.css'

type Props = {
  projectId: ProjectId
}

function ProjectProblemsTab({projectId}: Props) {
  return (
    <>
      <ModeSwitch
        userProperty={UserProperties.PROJECT_PROBLEMS_MODE}
        preserveParams={({projectTab}) => ({projectTab})}
        headerClassName={styles.header}
      >
        <Mode mode={Problems.TESTS} label={TESTS_TAB_LABEL}>
          <TestProblems projectId={projectId} />
        </Mode>
        <Mode mode={Problems.BUILD_PROBLEMS} label={BUILD_PROBLEMS_TAB_LABEL}>
          <BuildProblems projectId={projectId} />
        </Mode>
      </ModeSwitch>
    </>
  )
}

export default ProjectProblemsTab
