import {getProjectOverviewLocator} from '../../../../../../rest/locators'
import type {Branch} from '../../../../../../services/rest'
import type {BuildTypeId, ProjectId} from '../../../../../../types'
import {
  getBuildTypeFilter,
  getProjectBuildTypeFilter,
  getProjectFilter,
} from '../../../../../../types'

const MIN_AMOUNT_OF_FINISHED_BUILDS = 50
const MULTIPLE_FACTOR_FOR_QUEUED_COUNT = 2
export const getBuildTypeLineLocator = (
  buildTypeId: BuildTypeId | null | undefined,
  branch: Branch | null | undefined,
  branchesCount: number,
) => {
  const finishedCount =
    branchesCount < MIN_AMOUNT_OF_FINISHED_BUILDS ? MIN_AMOUNT_OF_FINISHED_BUILDS : branchesCount
  const runningCount = finishedCount * MULTIPLE_FACTOR_FOR_QUEUED_COUNT
  const queuedCount = finishedCount * MULTIPLE_FACTOR_FOR_QUEUED_COUNT

  return getProjectOverviewLocator({
    runningCount,
    queuedCount,
    finishedCount,
    branch,
    projectBuildtype: getProjectBuildTypeFilter({
      buildTypeId,
    }),
  })
}

export const getBranchesLocatorNode = (buildTypeId?: BuildTypeId, projectId?: ProjectId | null) => {
  if (buildTypeId) {
    return getBuildTypeFilter(buildTypeId)
  } else if (projectId) {
    return getProjectFilter(projectId)
  }

  return undefined
}
