import type {ComponentEnhancer} from 'recompose'
import {branch as branchHOC} from 'recompose'

import compose from 'lodash/flowRight'
import {useCallback, useMemo} from 'react'

import withHook from '../../../hocs/withHook'
import {withBranchProps, withBuildTypeId} from '../../../hooks/routes'
import {getBuildTypeArg} from '../../../rest/buildTypes'
import type {Branch} from '../../../services/rest'
import {restApi} from '../../../services/rest'
import type {BuildTypeId} from '../../../types'
import {getOldWebBuildTypeLink} from '../../../utils/entityLinks'
import ActionsDropdown from '../ActionsDropdown/ActionsDropdown.container'
import type {ActionsDropdownOwnProps} from '../ActionsDropdown/ActionsDropdown.types'
import {useSkipAssignInvestigation} from '../Investigations/Investigations.hooks'

type OwnProps = ActionsDropdownOwnProps & {
  buildTypeId?: BuildTypeId
}
type Props = OwnProps & {
  buildTypeId: BuildTypeId
  branch?: Branch | null
}

export default compose(
  branchHOC(
    (props: OwnProps) => props.buildTypeId == null,
    withBuildTypeId as ComponentEnhancer<Props, OwnProps>,
  ),
  withBranchProps,
  withHook(({buildTypeId, branch, inline}: Props) => {
    const [fetchSingleBuildTypeData] =
      restApi.endpoints.getBuildTypeNormalized.useLazyQuerySubscription()
    const update = useCallback(
      () => fetchSingleBuildTypeData(getBuildTypeArg(buildTypeId)),
      [buildTypeId, fetchSingleBuildTypeData],
    )
    const skipAssignInvestigation = useSkipAssignInvestigation(buildTypeId, branch, inline)

    return useMemo(
      () => ({
        update,
        skipAssignInvestigation,
        entityHref: getOldWebBuildTypeLink(buildTypeId),
      }),
      [buildTypeId, skipAssignInvestigation, update],
    )
  }),
)(ActionsDropdown)
