import alertService from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import type {ButtonAttrs} from '@jetbrains/ring-ui-built/components/button/button'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {useState} from 'react'
import {graphql} from 'react-relay'
import {useLocation, useNavigate} from 'react-router'

import {useMutationAsPromise} from '../../../hooks/relay/useMutationAsPromise'
import {usePermission} from '../../../hooks/usePermission'
import {extractErrorFromRelay} from '../../../relay/extractErrorFromRelay'
import {getPipelineHref} from '../../../routes'
import type {PipelineId, ProjectId} from '../../../types'
import {Permission} from '../../../types'
import {noop} from '../../../utils/empty'
import Tooltip from '../../pages/PipelinesPages/components/Tooltip/Tooltip'
import {usePipelineId} from '../../pages/PipelinesPages/hooks/pipeline'
import {serializeError} from '../../pages/PipelinesPages/utils/error'
import {
  isPipelinesEnabledInExclusiveMode,
  isWithoutVcsFeatureEnabled,
} from '../../pages/PipelinesPages/utils/featureToggles'

import type {RunPipelineButtonMutation} from './__generated__/RunPipelineButtonMutation.graphql'

import styles from './RunPipelineButton.module.css'

type Props = ButtonAttrs & {
  headId?: string | null
  projectId?: ProjectId | null
  beforeRun?: () => Promise<boolean>
  afterRun?: () => unknown
  pipelineId?: PipelineId
  branchName?: string | null
  hasVcsRoot?: boolean
  height?: ControlsHeight
  showRepositoryRequiredDialog?: () => void
}

const mutation = graphql`
  mutation RunPipelineButtonMutation($build: BuildInput!) {
    addBuildToQueue(input: $build) {
      id
    }
  }
`

const booleanNoop = () => Promise.resolve(true)

const popupProps = {
  offset: 10,
  autoPositioning: true,
  autoCorrectTopOverflow: true,
  directions: [Directions.BOTTOM_LEFT],
  className: styles.popup,
}
const noPermissionsMessage =
  'You do not have permissions to run this pipeline. Contact a project administrator to request access.'
export default function RunPipelineButton({
  headId,
  projectId,
  beforeRun = booleanNoop,
  afterRun = noop,
  children = 'Run',
  pipelineId,
  branchName,
  hasVcsRoot,
  height = ControlsHeight.M,
  showRepositoryRequiredDialog,
  ...restProps
}: Props) {
  const [isLoading, setIsLoading] = useState(false)
  const [addBuildToQueue] = useMutationAsPromise<RunPipelineButtonMutation>(mutation)
  const pipelineIdFromUrl = usePipelineId()
  const navigate = useNavigate()
  const location = useLocation()
  const canRunBuild = usePermission(Permission.RUN_BUILD, projectId)

  if (!isPipelinesEnabledInExclusiveMode() && !canRunBuild) {
    return null
  }

  return (
    <Tooltip popupProps={popupProps} title={canRunBuild ? null : noPermissionsMessage}>
      <Button
        height={height}
        disabled={!canRunBuild}
        onClick={async () => {
          if (!hasVcsRoot && isWithoutVcsFeatureEnabled) {
            showRepositoryRequiredDialog?.()
          } else {
            setIsLoading(true)
            try {
              const isValid = await beforeRun()
              if (isValid) {
                const data = await addBuildToQueue({
                  variables: {
                    build: {
                      buildType: {id: headId},
                      branchName,
                    },
                  },
                })
                const triggeredId = data.addBuildToQueue?.id
                afterRun()
                navigate(getPipelineHref(pipelineId ?? pipelineIdFromUrl, String(triggeredId)), {
                  state: {
                    isCreated: location?.state?.isCreated,
                  },
                })
              }
            } catch (e) {
              if (e instanceof Error) {
                alertService.error(serializeError(extractErrorFromRelay(e)))
              }
            } finally {
              setIsLoading(false)
            }
          }
        }}
        loader={isLoading}
        {...restProps}
      >
        {children}
      </Button>
    </Tooltip>
  )
}
