import {branch as branchHOC, renderComponent, withStateHandlers} from 'recompose'

import compose from 'lodash/flowRight'
import type * as React from 'react'
import {connect} from 'react-redux'

import {EntityProvider} from '../../../../../contexts/entity'
import type {State} from '../../../../../reducers/types'
import {getOverviewProject, getProject} from '../../../../../selectors'
import type {BuildTypeId, PipelineId, ProjectId} from '../../../../../types'
import {deduplicate} from '../../../../../utils/array'
import Loader from '../../../../common/Loader/Loader'
import ShowAllBuildTypes from '../../../../common/NestedSubprojectsAndBuildTypes/ShowAllBuildTypes/ShowAllBuildTypes'
import {withVisibility} from '../../../../common/Visible/Visible.hocs'
import {useHint} from '../../../../packages/Hints/Hints.hooks'

import {BuildTypesInfoTableContainer} from './BuildTypeInfoPanel/BuildTypeInfoPanel'
import BuildTypeInfo from './BuildTypeInfoPanel/BuildTypeInfoPanel.container'
import {buildTypeInfoPanelHint} from './BuildTypeInfoPanel/BuildTypeInfoPanel.hint'

type OuterProps = {
  projectId: ProjectId
  onlyFavorites: boolean
  showAll?: boolean
}
type OwnProps = OuterProps & {
  showAll: boolean
  isVisible: boolean
  handleShowAllClick: () => unknown
}
type StateProps = {
  overviewBuildTypeIds: ReadonlyArray<BuildTypeId>
  overviewPipelineIds: ReadonlyArray<PipelineId>
  buildTypeIds: ReadonlyArray<BuildTypeId>
  pipelineIds: ReadonlyArray<PipelineId>
  loading: boolean
}
type BuildSortedIds = {
  pipelineId?: PipelineId
  buildTypeId?: BuildTypeId
}

type Props = OwnProps & StateProps
const emptyArray: never[] = []

const mapStateToProps = (state: State, {projectId}: OwnProps): StateProps => {
  const overviewProject = getOverviewProject(state, projectId)
  const project = getProject(state, projectId)

  return {
    overviewBuildTypeIds: overviewProject?.buildTypes?.buildType ?? emptyArray,
    overviewPipelineIds: overviewProject?.pipelines?.pipeline ?? emptyArray,
    buildTypeIds: project?.buildTypes?.buildType ?? emptyArray,
    pipelineIds: project?.pipelines?.pipeline ?? emptyArray,
    loading: project == null && overviewProject == null,
  }
}

export default compose(
  withVisibility(false),
  withStateHandlers(
    ({showAll = false}: {showAll: boolean}) => ({
      showAll,
    }),
    {
      handleShowAllClick: () => () => ({
        showAll: true,
      }),
    },
  ),
  connect(mapStateToProps, {}),
  branchHOC(
    (props: StateProps) => props.loading,
    renderComponent(() => <Loader />),
  ),
)(
  ({
    overviewBuildTypeIds,
    overviewPipelineIds,
    buildTypeIds,
    pipelineIds,
    projectId,
    showAll,
    handleShowAllClick,
    onlyFavorites,
    isVisible,
  }: Props) => {
    useHint(isVisible && buildTypeInfoPanelHint)
    const buildTypesCount = buildTypeIds.length
    const overviewBuildTypesCount = overviewBuildTypeIds.length
    const showOnlyFavorites = onlyFavorites || (overviewBuildTypesCount > 0 && !showAll)
    const mergedBuildTypeIds = deduplicate([
      ...overviewBuildTypeIds,
      ...(!showOnlyFavorites ? buildTypeIds : []),
    ])
    const mergedPipelineIds = deduplicate([
      ...overviewPipelineIds,
      ...(showOnlyFavorites ? pipelineIds : []),
    ])
    const sortedIds: BuildSortedIds[] = [
      ...mergedPipelineIds.map(id => ({pipelineId: id})),
      ...mergedBuildTypeIds.map(id => ({buildTypeId: id})),
    ]
    const isShowButtonShowAllBuildTypes =
      !onlyFavorites && showOnlyFavorites && buildTypesCount > overviewBuildTypesCount

    return (
      <>
        <BuildTypesInfoTableContainer childCount={sortedIds.length}>
          {sortedIds.map(({pipelineId, buildTypeId}) => {
            const key = pipelineId ?? buildTypeId

            return (
              <EntityProvider key={key} pipelineId={pipelineId} buildTypeId={buildTypeId}>
                <BuildTypeInfo
                  pipelineId={pipelineId}
                  buildTypeId={buildTypeId}
                  projectId={projectId}
                />
              </EntityProvider>
            )
          })}
        </BuildTypesInfoTableContainer>
        {isShowButtonShowAllBuildTypes && (
          <ShowAllBuildTypes onClick={handleShowAllClick} count={buildTypesCount} />
        )}
      </>
    )
  },
) as React.ComponentType<OuterProps>
