import compose from 'lodash/flowRight'
import {connect} from 'react-redux'

import type {State} from '../../../../reducers/types'
import {
  makeGetFavoriteSubProjectIds,
  makeGetDirectNotArchivedSubProjectIds,
  makeGetDirectNotArchivedFavoriteSubProjectIds,
  getProjectsReady,
} from '../../../../selectors'
import {getOverviewReady} from '../../../../selectors/projectTrees'
import type {ProjectId} from '../../../../types'

import Subprojects from './Subprojects'

type OwnProps = {
  projectId: ProjectId
  parentProjectId: ProjectId
  onlyFavorites: boolean
}
type StateProps = {
  projectsReady: boolean
  notArchivedProjectIds: ReadonlyArray<ProjectId> | null | undefined
  favoriteProjectIds: ReadonlyArray<ProjectId>
}

const mapStateToProps: () => (state: State, props: OwnProps) => StateProps = () => {
  const getNotArchivedSubProjectIds = makeGetDirectNotArchivedSubProjectIds()
  const getNotArchivedFavoriteSubProjectIds = makeGetDirectNotArchivedFavoriteSubProjectIds()
  const getFavoriteSubProjectIds = makeGetFavoriteSubProjectIds()
  return (state, {projectId, parentProjectId, onlyFavorites}) => ({
    projectsReady: onlyFavorites
      ? getOverviewReady(state)
      : getProjectsReady(state, parentProjectId),
    notArchivedProjectIds: onlyFavorites
      ? getNotArchivedFavoriteSubProjectIds(state, projectId)
      : getNotArchivedSubProjectIds(state, projectId),
    favoriteProjectIds: getFavoriteSubProjectIds(state, projectId),
  })
}

export default compose(connect(mapStateToProps))(Subprojects)
