import {objectToQuery} from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import {useCallback, useEffect, useMemo} from 'react'

import {useLazyLoading} from '../../../../hocs/withLazyLoading'
import {useBuildTypeId, useProjectId} from '../../../../hooks/routes'
import useMyId from '../../../../hooks/useMyId'
import {restApi} from '../../../../services/rest'
import {stringifyId} from '../../../../types'
import {Namespace} from '../../../../utils/namespace'
import {subscribeOnUserEvents} from '../../../../utils/subscriber'
import {USER_PERMISSIONS_CHANGED} from '../../../../utils/subscriptionEvents'
import Badge from '../../Badge/Badge'
import {InjectHtml} from '../../InjectHtml/InjectHtml'
import {useSequenceLoaderReadyHandler} from '../../SequenceLoader/SequenceLoader.hooks'
import type {SeqProps} from '../../SequenceLoader/SequenceLoader.types'

import styles from './HealthBadge.module.css'

const noItemsLabel = 'No items to show'

type Props = {
  className?: string
} & SeqProps
function HealthBadge({className}: Props) {
  const buildTypeId = useBuildTypeId()
  const projectId = useProjectId()

  const path = `${
    buildTypeId != null ? 'buildTypeHealthStatusItems.html' : 'projectHealthStatusItems.html'
  }?${objectToQuery({
    buildTypeId: stringifyId(buildTypeId),
    projectId: stringifyId(projectId),
    compute: 'true',
    excludeCategoryId: 'suggestion',
    dropdown: 'true',
  })}`
  const myId = useMyId()

  const [fetchHtml, {content}, lastPromiseInfo] = restApi.endpoints.getHtml.useLazyQuery({
    selectFromResult: ({data}) => ({content: data}),
  })

  const arg = useMemo(() => (path != null ? {path} : null), [path])
  const load = useCallback(() => {
    if (arg != null) {
      fetchHtml(arg)
    }
  }, [arg, fetchHtml])

  const isReady = lastPromiseInfo.lastArg === arg

  const lazyLoadingProps = useLazyLoading<string>({
    namespace: Namespace.HTML,
    childUsesVisibility: false,
    ignoreFetcher: true,
    id: path ?? '',
    needsDetails: !isReady,
    fetchDetails: load,
  })

  useEffect(
    () =>
      myId != null && path != null
        ? subscribeOnUserEvents(`html:${path}`, myId, [USER_PERMISSIONS_CHANGED], load)
        : undefined,
    [load, myId, path],
  )

  useSequenceLoaderReadyHandler(isReady && content != null)

  return (
    <Badge
      dataTestId={'health-badge'}
      className={styles.badge}
      label={buildTypeId ? 'Configuration health' : 'Project health'}
      clickable={!!content && !content?.includes(noItemsLabel)}
    >
      {!content ? (
        <span>{noItemsLabel}</span>
      ) : (
        <span className={classNames(styles.healthItems, 'healthItemIndicatorContainer', className)}>
          <InjectHtml {...lazyLoadingProps} content={content} showLoader={false} />
        </span>
      )}
    </Badge>
  )
}
export default HealthBadge
