import * as React from 'react'
import {memo, Suspense} from 'react'

import {UpdateProvider} from '../../../../../../contexts/update'
import createSimpleStream from '../../../../../../utils/simpleStream'
import {BuildsWrappedPlaceholder} from '../../../../../common/Builds/Builds.wrapped'
import {DEBOUNCE_PERIOD} from '../../../../../common/Fetcher/Fetcher'
import NestedBuildTypeLine from '../../../../../common/NestedSubprojectsAndBuildTypes/BuildTypeLine/BuildTypeLine'

import BuildTypeLineFetcher from './BuildTypeLine.fetcher'
import type {ContainerProps} from './BuildTypeLine.types'

const NO_BUILDS = 'No builds'

function BuildTypeLine(props: ContainerProps) {
  const {buildTypeId, pipelineId, nested} = props

  const [hasBuilds, setHasBuilds] = React.useState<boolean | null>(null)

  const onLoadingComplete = React.useCallback((arg1: boolean) => setHasBuilds(arg1), [])

  const update$ = React.useMemo(() => createSimpleStream(DEBOUNCE_PERIOD), [])

  return (
    <UpdateProvider update={update$.fire}>
      <NestedBuildTypeLine {...props} hasContent={hasBuilds} emptyText={NO_BUILDS}>
        <Suspense fallback={<BuildsWrappedPlaceholder hasParentGrid />}>
          <BuildTypeLineFetcher
            onLoadingComplete={onLoadingComplete}
            update$={update$}
            pipelineId={pipelineId}
            buildTypeId={buildTypeId}
            nested={nested}
          />
        </Suspense>
      </NestedBuildTypeLine>
    </UpdateProvider>
  )
}

export default memo(BuildTypeLine)
