import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import {Suspense, useMemo} from 'react'
import {graphql, useLazyLoadQuery} from 'react-relay'

import useStatusSubscription from '../../../../hooks/useStatusSubscription'
import {getBranchesLocator, Policy} from '../../../../rest/branches'
import {getOverviewHref} from '../../../../routes'
import {getStatus} from '../../../../selectors'
import type {Branch} from '../../../../services/rest'
import type {BuildTypeId, ProjectOrBuildTypeStatus} from '../../../../types'
import {
  getBuildTypeStatusRequest,
  BuildTypePageTabNamesEnum,
  getBuildTypeFilter,
} from '../../../../types'
import {internalProps} from '../../../../types/BS_types'
import {defaultBranch, parseBranch, stringifyBranch} from '../../../../utils/branchNames'
import {useHasNonDefaultBranches} from '../../../common/BranchSelect/BranchSelect.hooks'
import {getChangesLocator, getPendingChangesBaseLocator} from '../Changes.utils'
import ChangesDropdown from '../ChangesDropdown/ChangesDropdown'
import styles from '../ChangesDropdown/ChangesDropdown.module.css'
import ChangesDropdownContent from '../ChangesDropdownContent/ChangesDropdownContent'
import ChangesDropdownLink from '../ChangesDropdownLink/ChangesDropdownLink'

import type {PendingChangesDropdownWithBranchesQuery} from './__generated__/PendingChangesDropdownWithBranchesQuery.graphql'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  className?: string
  linkClassName?: string
  buildTypeId: BuildTypeId
  branch?: Branch | null | undefined
  addDefaultWordAnyway?: boolean
}

const CHANGES_LIMIT = Number(internalProps['teamcity.internal.buildChangesPopupLimit'])

const withBranchesQuery = graphql`
  query PendingChangesDropdownWithBranchesQuery($locator: String, $btLocator: String!) {
    branchesOfBuildType(locator: $locator, btLocator: $btLocator) {
      ...BranchSelect_hasNonDefaultBranches
    }
  }
`

function PendingChangesDropdown(props: Props) {
  const {linkClassName, buildTypeId} = props

  const branchLocator = getBranchesLocator({
    node: getBuildTypeFilter(buildTypeId),
    policy: Policy.ALL_BRANCHES,
  })
  const {branchesOfBuildType = null} = useLazyLoadQuery<PendingChangesDropdownWithBranchesQuery>(
    withBranchesQuery,
    {
      locator: branchLocator,
      btLocator: `id:${buildTypeId}`,
    },
  )
  const withBranches = useHasNonDefaultBranches(branchesOfBuildType)

  const branch = props.branch == null || props.branch.groupFlag ? defaultBranch : props.branch
  const statusRequest = getBuildTypeStatusRequest(buildTypeId, parseBranch(stringifyBranch(branch)))
  const changesCount = useAppSelector(state => getStatus(state, statusRequest)?.pending ?? 0)

  const locator = getChangesLocator({
    baseLocator: getPendingChangesBaseLocator(buildTypeId, branch),
    count: CHANGES_LIMIT,
    lookupLimit: CHANGES_LIMIT,
  })

  const changesCountLimitExceeded = useAppSelector(state => {
    const statusObj: ProjectOrBuildTypeStatus | null | undefined = getStatus(state, statusRequest)
    return statusObj?.pendingLimitExceeded ?? false
  })

  const label = useMemo(() => {
    if (!changesCountLimitExceeded && changesCount === 0) {
      return null
    }

    return (
      <span>
        {`${changesCountLimitExceeded ? `${CHANGES_LIMIT}+` : changesCount} pending`}
        {withBranches && (props.branch == null || props.branch.groupFlag) ? (
          <>
            {' in '}
            <SvgIcon icon="branches" className={styles.branchIcon} />
            {' Default'}
          </>
        ) : null}
      </span>
    )
  }, [changesCount, changesCountLimitExceeded, props.branch, withBranches])

  const branchNameInHref = encodeURIComponent(stringifyBranch(branch))
  const href = `${getOverviewHref({
    buildTypeId,
  })}?branch=${branchNameInHref}&buildTypeTab=${BuildTypePageTabNamesEnum.PENDING_CHANGES}`

  useStatusSubscription({buildTypeId, branch})

  const renderLabel = useMemo(
    () =>
      label != null ? (
        <ChangesDropdownLink
          className={linkClassName}
          locator={locator}
          href={href}
          label={label}
        />
      ) : null,
    [href, label, linkClassName, locator],
  )

  return (
    <ChangesDropdown label={renderLabel} isPending>
      <ChangesDropdownContent
        buildTypeId={buildTypeId}
        branch={branch}
        changesCount={changesCount}
        isPending
      />
    </ChangesDropdown>
  )
}

export default function PendingChangesDropdownContainer(props: Props) {
  return (
    <Suspense>
      <PendingChangesDropdown {...props} />
    </Suspense>
  )
}
