import classNames from 'classnames'
import {Suspense, useMemo} from 'react'

import {useIsAutodetectTimeZone} from '../../../hooks/useIsAutodetectTimeZone'
import {getBuildTypeArg} from '../../../rest/buildTypes'
import {getBuildType} from '../../../selectors'
import {restApi} from '../../../services/rest'
import type {BuildTypeId} from '../../../types'

import ActivateButton from './ActivateButton/ActivateButton'
import {getDetails} from './BuildTypePauseInfo.utils'

import styles from './BuildTypePauseInfo.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  className?: string
  buildTypeId: BuildTypeId
  lineBreakBeforeButton?: boolean
}

function BuildTypePauseInfo({className, buildTypeId, lineBreakBeforeButton = false}: Props) {
  const isAutodetectTimeZone = useIsAutodetectTimeZone()
  const {pauseComment} = restApi.endpoints.getBuildTypeNormalized.useQuery(
    getBuildTypeArg(buildTypeId),
    {
      selectFromResult: ({data}) => {
        const {result, entities} = data ?? {}
        return {
          pauseComment: entities?.buildTypes?.[result!]?.pauseComment,
        }
      },
    },
  )
  const projectId = useAppSelector(state => getBuildType(state, buildTypeId)?.projectId)
  const details = useMemo(
    () => getDetails(pauseComment, isAutodetectTimeZone),
    [isAutodetectTimeZone, pauseComment],
  )

  return (
    <div className={classNames(styles.container, className)}>
      <span>{details}</span>
      <Suspense>
        <ActivateButton
          projectId={projectId}
          buildTypeId={buildTypeId}
          text={pauseComment?.text}
          newLineBeforeButton={lineBreakBeforeButton}
        />
      </Suspense>
    </div>
  )
}

export default BuildTypePauseInfo
