import {
  ControlsHeight,
  ControlsHeightContext,
} from '@jetbrains/ring-ui-built/components/global/controls-height'
import {PlaceId} from '@jetbrains/teamcity-ui/dist/plugin'
import classNames from 'classnames'
import {memo} from 'react'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import {useIsFavoriteProjectsLinkSelected, useQueryParam} from '../../../../hooks/routes'
import useDocumentTitle from '../../../../hooks/useDocumentTitle'
import {usePermission} from '../../../../hooks/usePermission'
import useStatusSubscription from '../../../../hooks/useStatusSubscription'
import {Policy} from '../../../../rest/branches'
import {getProject} from '../../../../selectors'
import {getHasFavoriteProjects} from '../../../../selectors/projectTrees'
import type {ProjectId} from '../../../../types'
import {Permission, ProjectPageTabNamesEnum, ROOT_PROJECT_ID} from '../../../../types'
import BranchFilterBadge from '../../../common/Badges/BranchFilterBadge/BranchFilterBadge'
import HealthBadge from '../../../common/Badges/HealthBadge/HealthBadge'
import ResponsiveBadgeContainer from '../../../common/Badges/ResponsiveBadgeContainer/ResponsiveBadgeContainer'
import type {BranchSelectBranchesQuery} from '../../../common/BranchSelect/__generated__/BranchSelectBranchesQuery.graphql'
import CreateEntityButton from '../../../common/CreateEntityButton/CreateEntityButton.container'
import Description from '../../../common/Description/Description.container'
import EditEntity from '../../../common/EditEntity/EditEntity.container'
import FavoriteStar from '../../../common/FavoriteStar/FavoriteStar.container'
import NoWrap from '../../../common/NoWrap/NoWrap'
import PageTitle from '../../../common/PageTitle/PageTitle'
import Plugin from '../../../common/Plugin/Plugin'
import OverviewHeaderIcon from '../../../common/ProjectOrBuildTypeIcon/OverviewHeaderIcon.container'
import SequenceLoader from '../../../common/SequenceLoader/SequenceLoader'

import OverviewArchivedProjectInfo from './OverviewArchivedProjectInfo/OverviewArchivedProjectInfo'

import styles from './ProjectPageHeader.module.css'

import EditProjectSidebar from 'src/components/common/EditProjectSidebar/EditProjectSidebar'
import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  className?: string
  projectId: ProjectId
  branchesQueryRef?: PreloadedQuery<BranchSelectBranchesQuery>
}

const icon = <OverviewHeaderIcon size="L" />

function ProjectPageHeader({className, projectId, branchesQueryRef}: Props) {
  const isFavoriteProjectsPage = useIsFavoriteProjectsLinkSelected()
  const isProblemsTab = useQueryParam('projectTab') === ProjectPageTabNamesEnum.PROBLEMS
  const project = useAppSelector(state => getProject(state, projectId))
  const isFavorites = useAppSelector(
    state => (isFavoriteProjectsPage && getHasFavoriteProjects(state)) || false,
  )
  const canEditOwnProfile = usePermission(Permission.CHANGE_OWN_PROFILE, ROOT_PROJECT_ID)
  const title = project?.name
  const projectArchived = Boolean(project?.archived)

  const actualTitle = isFavorites
    ? 'Favorite Projects'
    : isFavoriteProjectsPage
      ? 'All Projects'
      : title
  const headingClassNames = classNames(styles.heading, className, {
    [styles.projectArchived]: projectArchived,
  })

  useStatusSubscription({projectId})
  useDocumentTitle(actualTitle != null ? `${actualTitle} — TeamCity` : null)

  return (
    <div data-test="overview-header" data-project-id={projectId} className={styles.header}>
      <div className={styles.top}>
        <PageTitle className={headingClassNames}>
          {!isFavoriteProjectsPage && icon}
          <span className={styles.title}>{actualTitle}</span>
          {projectArchived && <OverviewArchivedProjectInfo className={styles.archived} />}
          {!isFavoriteProjectsPage && !projectArchived && (
            <NoWrap>
              <FavoriteStar className={styles.star} projectId={projectId} />
            </NoWrap>
          )}
        </PageTitle>
        <ControlsHeightContext.Provider value={ControlsHeight.M}>
          <Plugin placeId={PlaceId.SAKURA_PROJECT_LINKS} />
          <SequenceLoader className={styles.topSequenceLoader} loader="" reverse>
            <CreateEntityButton seqKey="CreateDropdown" withBorder />
            {!isFavoriteProjectsPage && <EditEntity seqKey="EditEntity" />}
          </SequenceLoader>
        </ControlsHeightContext.Provider>
      </div>
      {!isFavoriteProjectsPage && (
        <>
          <Description className={styles.description} lines={3} projectId={projectId} />
          <ResponsiveBadgeContainer className={styles.subHeader}>
            {!isProblemsTab && (
              <BranchFilterBadge
                seqKey="branchBadge"
                headId={projectId}
                branchesQueryRef={branchesQueryRef}
                policy={Policy.ACTIVE_HISTORY_AND_ACTIVE_VCS_BRANCHES}
              />
            )}
            <HealthBadge seqKey="healthBadge" />
          </ResponsiveBadgeContainer>
        </>
      )}
      {isFavoriteProjectsPage && (
        <div className={styles.actions}>
          {canEditOwnProfile && !projectArchived && (
            <EditProjectSidebar seqKey="EditProjectSidebar" button projectId={projectId} />
          )}
        </div>
      )}
    </div>
  )
}
export default memo(ProjectPageHeader)
