import {connect} from 'react-redux'

import type {State} from '../../../../../reducers/types'
import {getBuildType, getStatus} from '../../../../../selectors'
import {getBuildTypeStatusRequest} from '../../../../../types'
import type {ProjectOrBuildTypeStatus, SystemProblem} from '../../../../../types'

import OverviewSystemProblems from './OverviewSystemProblems'
import type {OwnProps, StateProps} from './OverviewSystemProblems.types'

const emptyArray: SystemProblem[] = []

const mapStateToProps = (state: State, {buildTypeId, branch}: OwnProps): StateProps => {
  const statusObj: ProjectOrBuildTypeStatus | null | undefined =
    buildTypeId != null ? getStatus(state, getBuildTypeStatusRequest(buildTypeId, branch)) : null
  const systemProblems: ReadonlyArray<SystemProblem> = statusObj?.systemProblems
    ? statusObj.systemProblems
    : emptyArray
  const additionalProblems: ReadonlyArray<SystemProblem> = statusObj?.additionalProblems
    ? statusObj.additionalProblems
    : emptyArray
  const projectId = getBuildType(state, buildTypeId)?.projectId
  return {
    systemProblems,
    additionalProblems,
    projectId,
  }
}

export default connect(mapStateToProps)(OverviewSystemProblems)
