import {withProps} from 'recompose'

import classNames from 'classnames'
import compose from 'lodash/flowRight'
import * as React from 'react'
import {connect} from 'react-redux'

import {subscribeOnBuildTypeStatus} from '../../../../../actions/statuses'
import withStatusSubscription from '../../../../../hocs/withStatusSubscription'
import {useAppDispatch} from '../../../../../hooks/react-redux'
import type {State} from '../../../../../reducers/types'
import {getStatus, makeGetProjectBuildTypes} from '../../../../../selectors'
import type {BuildType} from '../../../../../services/rest'
import {getStatusRequest} from '../../../../../types'
import type {ProjectId} from '../../../../../types'
import {subprojectStatusesHint} from '../../../../packages/Hints/HintItems/Hints.projectOverview'
import {useHint} from '../../../../packages/Hints/Hints.hooks'
import CreateEntityButton from '../../../CreateEntityButton/CreateEntityButton.container'
import ProjectOrBuildTypeIcon from '../../../ProjectOrBuildTypeIcon/ProjectOrBuildTypeIcon'
import {EntityIconType} from '../../../ProjectOrBuildTypeIcon/ProjectOrBuildTypeIcon.types'
import {withVisibility} from '../../../Visible/Visible.hocs'

import styles from './Subproject.module.css'

type StateProps = {
  success: number
  failed: number
  unknown: number
  buildTypes: ReadonlyArray<BuildType>
}
type OwnProps = {
  projectId: ProjectId
  isVisible: boolean
  blockUpdates: boolean
  hasChildren: boolean
}
type Props = StateProps & OwnProps

function SubprojectDetails({success, unknown, failed, buildTypes, isVisible, hasChildren}: Props) {
  useHint(isVisible && unknown + failed + success > 0 && subprojectStatusesHint)
  const dispatch = useAppDispatch()
  React.useEffect(() => {
    const unsubscribe = (topics: (() => unknown)[]) => topics.forEach(cancel => cancel())

    const topics: (() => unknown)[] = []

    if (isVisible) {
      buildTypes.forEach(
        (buildType: BuildType) =>
          buildType.internalId != null &&
          topics.push(
            dispatch(subscribeOnBuildTypeStatus(buildType.id, buildType.internalId, null)),
          ),
      )
    }

    return () => unsubscribe(topics)
  }, [buildTypes, isVisible, dispatch])

  return (
    <div className={styles.actions} data-hint-container-id={subprojectStatusesHint.id}>
      {unknown > 0 && (
        <span
          className={classNames(styles.status, styles.unknown)}
          title={'Build configurations with unknown status'}
        >
          <span className={styles.count}>{unknown}</span>
          <ProjectOrBuildTypeIcon className={styles.statusIcon} type={EntityIconType.BUILD_TYPE} />
        </span>
      )}
      {failed > 0 && (
        <span
          className={classNames(styles.status, styles.failed)}
          title={'Build configurations with failed builds in default branch'}
        >
          <span className={styles.count}>{failed}</span>
          <ProjectOrBuildTypeIcon
            className={styles.statusIcon}
            type={EntityIconType.BUILD_TYPE}
            status={'failed'}
          />
        </span>
      )}
      {success > 0 && (
        <span
          className={classNames(styles.status, styles.success)}
          title={'Build configurations with successful builds in default branch'}
        >
          <span className={styles.count}>{success}</span>
          <ProjectOrBuildTypeIcon
            className={styles.statusIcon}
            type={EntityIconType.BUILD_TYPE}
            status={'successful'}
          />
        </span>
      )}
      {!hasChildren && (
        <span className={classNames(styles.noChildrenWarning, styles.minorInfo)}>
          {'Empty project'}
        </span>
      )}
      <CreateEntityButton className={styles.add} />
    </div>
  )
}

const mapStateToProps: () => (arg0: State, arg1: OwnProps) => StateProps = () => {
  const getProjectBuildTypes = makeGetProjectBuildTypes()
  return (state: State, {projectId}: OwnProps): StateProps => {
    const buildTypes = getProjectBuildTypes(state, projectId)
    const statuses = buildTypes.map(buildType =>
      getStatus(state, getStatusRequest({type: 'bt', id: buildType.id})),
    )
    let success = 0
    let failed = 0
    let unknown = 0
    statuses.forEach(node => {
      if (node?.status === 'SUCCESS') {
        success++
      } else if (node?.status === 'FAILURE') {
        failed++
      } else if (node?.status === 'UNKNOWN') {
        unknown++
      }
    })
    return {
      success,
      failed,
      unknown,
      buildTypes,
    }
  }
}

const SubprojectDetailsContainer = compose(
  React.memo,
  withVisibility(),
  withProps(() => ({
    blockUpdates: true,
  })),
  withStatusSubscription(),
  connect(mapStateToProps, null),
)(SubprojectDetails)
SubprojectDetailsContainer.displayName = 'Subproject Details Container'
export default SubprojectDetailsContainer
