import compose from 'lodash/flowRight'
import * as React from 'react'
import {connect} from 'react-redux'

import {toggleSubproject} from '../../../../../actions'
import {useDerivedState} from '../../../../../hocs/withDerivedState'
import withHook from '../../../../../hocs/withHook'
import withStatusSubscription from '../../../../../hocs/withStatusSubscription'
import type {State} from '../../../../../reducers/types'
import {
  getHasBuildConfigurations,
  getIsSubprojectCollapsed,
  getOverviewProject,
  getProject,
  makeGetIsFavoriteSubprojectsExist,
  makeGetIsSubprojectsExist,
} from '../../../../../selectors'
import type {ProjectId} from '../../../../../types'
import type {VisibleProps} from '../../../Visible/Visible.hocs'
import {withVisibility} from '../../../Visible/Visible.hocs'

import Subproject from './Subproject'

type OwnProps = {
  projectId: ProjectId
  wasVisible?: boolean
  onlyFavorites?: boolean
}
export default compose(
  React.memo,
  withVisibility(true),
  withHook(({isVisible}: VisibleProps) => {
    const wasVisible = useDerivedState(false, state => state || isVisible === true)
    return {
      wasVisible,
      blockUpdates: !wasVisible,
    }
  }),
  withStatusSubscription(),
  connect(
    () => {
      const getHasSubprojects = makeGetIsSubprojectsExist()
      const getHasFavoriteSubprojects = makeGetIsFavoriteSubprojectsExist()
      return (state: State, {projectId, wasVisible, onlyFavorites}: OwnProps) => {
        const project = onlyFavorites
          ? getOverviewProject(state, projectId)
          : getProject(state, projectId)
        const hasSubprojects = onlyFavorites
          ? getHasFavoriteSubprojects(state, projectId)
          : getHasSubprojects(state, projectId)

        return {
          isArchived: project?.archived ?? false,
          isExpanded: !getIsSubprojectCollapsed(state, projectId),
          hasSubprojects: wasVisible ? hasSubprojects : true,
          hasBuildTypes: getHasBuildConfigurations(state, projectId, onlyFavorites),
          name: project?.name,
        }
      }
    },
    (dispatch, {projectId}) => ({
      toggleSubproject: (expand: boolean) => dispatch(toggleSubproject(projectId, expand)),
    }),
  ),
)(Subproject)
