import classNames from 'classnames'
import {useCallback} from 'react'

import type {BuildTypeId, PipelineId} from '../../../../../types'
import {useBuildsClassName} from '../../../../common/Builds/Builds'
import BuildTypes from '../../../../common/NestedSubprojectsAndBuildTypes/BuildTypes/BuildTypes.container'
import {BuildTypesContext} from '../../../../common/NestedSubprojectsAndBuildTypes/BuildTypes/BuildTypesContext'

import type {OwnProps} from './BuildsByBuildType.types'
import BuildTypeLine from './BuildTypeLine/BuildTypeLine'

import styles from './BuildsByBuildType.module.css'

export default function BuildsByBuildType({projectId, onlyFavorites = false, nested}: OwnProps) {
  const buildsClassName = classNames(styles.container, useBuildsClassName())

  const nestedRender = useCallback(
    (
      archivedProject: boolean,
      isFavorite: boolean,
      buildTypeId?: BuildTypeId,
      pipelineId?: PipelineId,
    ) => (
      <BuildTypeLine
        pipelineId={pipelineId}
        buildTypeId={buildTypeId}
        archivedProject={archivedProject}
        isFavorite={isFavorite}
        nested={nested}
      />
    ),
    [nested],
  )

  return (
    <BuildTypesContext.Provider value={nestedRender}>
      <BuildTypes
        projectId={projectId}
        onlyFavorites={onlyFavorites}
        gridClassName={buildsClassName}
      />
    </BuildTypesContext.Provider>
  )
}
