import compose from 'lodash/flowRight'
import {memo} from 'react'

import withSuspense from '../../../hocs/withSuspense'
import {projectCreateHint} from '../../packages/Hints/HintItems/Hints.projectOverview'

import CreateEntityButton from './CreateEntityButton'
import type {Props as BaseProps} from './CreateEntityButton'
import {useCreateEntityButton} from './CreateEntityButton.hooks'

type Props = Omit<BaseProps, 'actions'> & {
  seqKey?: string
}
function CreateEntityButtonContainer({seqKey, ...restProps}: Props) {
  const actions = useCreateEntityButton()

  return (
    <CreateEntityButton
      actions={actions}
      {...restProps}
      data-hint-container-id={projectCreateHint.id}
    />
  )
}
export default compose(memo, withSuspense())(CreateEntityButtonContainer)
