import type {ButtonAttrs} from '@jetbrains/ring-ui-built/components/button/button'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import classNames from 'classnames'
import plur from 'plur'

import {useSequenceLoaderReadyHandler} from '../../SequenceLoader/SequenceLoader.hooks'
import type {SeqProps} from '../../SequenceLoader/SequenceLoader.types'

import styles from './ShowAllBuildTypes.module.css'

type Props = ButtonAttrs &
  SeqProps & {
    count: number
    className?: string
  }

function ShowAllBuildTypes({count, className, seqKey, ...restProps}: Props) {
  useSequenceLoaderReadyHandler(true)
  return (
    <Button
      inline
      className={classNames(styles.button, className)}
      {...restProps}
    >{`Show all ${count} ${plur('configuration', count)}`}</Button>
  )
}

export default ShowAllBuildTypes
