import {withHandlers} from 'recompose'

import chevronDown from '@jetbrains/icons/chevron-down.svg'
import chevronRight from '@jetbrains/icons/chevron-right.svg'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import {H2} from '@jetbrains/ring-ui-built/components/heading/heading'
import Icon from '@jetbrains/ring-ui-built/components/icon/icon'
import classNames from 'classnames'
import compose from 'lodash/flowRight'
import * as React from 'react'
import {connect} from 'react-redux'

import {toggleBuildType, togglePipeline} from '../../../../actions'
import EntityLink from '../../../../containers/EntityLink'
import {withOneLineProp} from '../../../../contexts/oneLine'
import {useDerivedState} from '../../../../hocs/withDerivedState'
import {withBranchProps} from '../../../../hooks/routes'
import type {State} from '../../../../reducers/types'
import {
  getBuildType,
  getBuildTypeDescription,
  getPipeline,
  isBuildTypeCollapsed,
  isPipelineCollapsed,
} from '../../../../selectors'
import type {Branch} from '../../../../services/rest'
import type {BuildTypeId, PipelineId} from '../../../../types'
import PendingChangesDropdown from '../../../packages/Changes/PendingChangesDropdown/PendingChangesDropdown'
import OverviewSystemProblems from '../../../pages/BuildTypePage/BuildTypePageHeader/OverviewSystemProblems/OverviewSystemProblems.container'
import OverviewBuildTypeActions from '../../BuildTypeActionsDropdown/BuildTypeActionsDropdown'
import Details from '../../Details/Details'
import FavoriteStar from '../../FavoriteStar/FavoriteStar.container'
import RowGroup from '../../Grid/RowGroup'
import MiddleEllipsis from '../../MiddleEllipsis/MiddleEllipsis'
import OverviewStatusIcon from '../../ProjectOrBuildTypeIcon/OverviewStatusIcon.container'
import {EntityIconType} from '../../ProjectOrBuildTypeIcon/ProjectOrBuildTypeIcon.types'
import RunBuildButtonGroup from '../../RunBuild/RunBuildInSelectedBranch.container'
import RunPipelineButton from '../../RunPipelineButton/RunPipelineButton'
import {
  SequenceLoaderContext,
  sequenceLoaderDefaultContext,
  useSequenceLoaderReadyHandler,
} from '../../SequenceLoader/SequenceLoader.hooks'
import {useVisibility} from '../../Visible/Visible.hooks'

import type {
  ContainerActionProps,
  ContainerOwnProps,
  ContainerProps,
  ContainerStateProps,
} from './BuildTypeLine.types'
import BuildTypePauseDropdown from './BuildTypePauseDropdown/BuildTypePauseDropdown'

import styles from './BuildTypeLine.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type ChangesColumnContentProps = {
  buildTypeId?: BuildTypeId
  pipelineId?: PipelineId
  branch: Branch
}

const mapStateToProps = (
  state: State,
  {isFavorite, buildTypeId, pipelineId}: ContainerOwnProps,
): ContainerStateProps => {
  let expanded = false

  if (buildTypeId) {
    expanded = !isBuildTypeCollapsed(state, buildTypeId, !isFavorite)
  } else if (pipelineId) {
    expanded = !isPipelineCollapsed(state, pipelineId, !isFavorite)
  }

  return {
    expanded,
  }
}

const actionCreators: ContainerActionProps = {
  toggleBuildTypeExpand: toggleBuildType,
  togglePipelineExpand: togglePipeline,
}

const ChangesColumnContent = React.memo(({buildTypeId, branch}: ChangesColumnContentProps) => {
  const ref = React.useRef<HTMLDivElement>(null)
  const isVisible = useVisibility(ref)
  const wasVisible = useDerivedState(false, state => state || isVisible)
  const isShowPendingChanges = wasVisible && buildTypeId

  return (
    <div ref={ref}>
      {isShowPendingChanges ? (
        <PendingChangesDropdown buildTypeId={buildTypeId} branch={branch} />
      ) : null}
    </div>
  )
})
ChangesColumnContent.displayName = 'ChangesColumnContent'

function BuildTypeLine(props: ContainerProps) {
  const {
    buildTypeId,
    pipelineId,
    branch,
    oneLine,
    expanded,
    archivedProject,
    toggleExpand,
    hasContent,
    emptyText,
    children,
  } = props

  const buildTypeName = useAppSelector(state => getBuildType(state, buildTypeId)?.name)
  const pipelineName = useAppSelector(state => getPipeline(state, pipelineId)?.name)
  const pipelineHead = useAppSelector(state => getPipeline(state, pipelineId)?.headBuildType)
  const name = buildTypeId ? buildTypeName : pipelineName
  const description = useAppSelector(state => getBuildTypeDescription(state, buildTypeId) ?? null)
  const paused = useAppSelector(state => getBuildType(state, buildTypeId)?.paused ?? false)

  const summaryClass = classNames(styles.root, {
    [styles.oneLine]: oneLine,
    [styles.expanded]: expanded,
  })

  const buildTypeInfoClasses = classNames(styles.buildTypeInfo)
  const isShowFavaoriteStar = !archivedProject && !pipelineId
  const isShowBuildTypePauseDropdown = paused && buildTypeId
  const isShowOverviewSystemProblems = !!buildTypeId

  const actionsContent = React.useMemo(
    () => (
      <div className={styles.runColumn}>
        {buildTypeId ? (
          <RunBuildButtonGroup buildTypeId={buildTypeId} />
        ) : (
          <RunPipelineButton
            pipelineId={pipelineId}
            headId={pipelineHead?.id}
            projectId={pipelineHead?.projectId}
            branchName={branch?.default ? undefined : branch?.name}
            height={ControlsHeight.S}
            hasVcsRoot
          />
        )}
        {buildTypeId && (
          <OverviewBuildTypeActions
            inline
            preload
            buildTypeId={buildTypeId}
            className={styles.actions}
          />
        )}
      </div>
    ),
    [
      branch?.default,
      branch?.name,
      buildTypeId,
      pipelineHead?.id,
      pipelineHead?.projectId,
      pipelineId,
    ],
  )
  const Summary = React.useMemo(
    () => (
      <SequenceLoaderContext.Provider value={sequenceLoaderDefaultContext}>
        <RowGroup>
          <div className={buildTypeInfoClasses}>
            <H2 className={styles.buildTypeName}>
              {buildTypeId ? (
                <OverviewStatusIcon
                  type={EntityIconType.BUILD_TYPE}
                  id={buildTypeId}
                  size="M"
                  showInvestigationInStatus
                />
              ) : (
                <OverviewStatusIcon
                  type={EntityIconType.PIPELINE}
                  id={pipelineId}
                  size="M"
                  showInvestigationInStatus
                />
              )}

              <EntityLink
                title={name}
                pipelineId={pipelineId}
                buildTypeId={buildTypeId}
                className={styles.link}
              >
                <MiddleEllipsis tailLength={3} className={styles.caption}>
                  {name}
                </MiddleEllipsis>
              </EntityLink>
            </H2>
            {isShowFavaoriteStar && (
              <FavoriteStar buildTypeId={buildTypeId} className={styles.star} />
            )}
            {hasContent === false && <span className={styles.empty}>{emptyText}</span>}
            {description != null && (
              <span className={styles.description}>
                <MiddleEllipsis tailLength={5}>{description}</MiddleEllipsis>
              </span>
            )}
            {isShowBuildTypePauseDropdown && <BuildTypePauseDropdown buildTypeId={buildTypeId} />}
            {isShowOverviewSystemProblems && (
              <OverviewSystemProblems
                className={styles.systemProblems}
                buildTypeId={buildTypeId}
                pipelineId={pipelineId}
                branch={branch}
              />
            )}
          </div>
          <div className={styles.changes}>
            <ChangesColumnContent
              pipelineId={pipelineId}
              buildTypeId={buildTypeId}
              branch={branch}
            />
          </div>
          {actionsContent}
          <Icon
            glyph={expanded ? chevronDown : chevronRight}
            className={classNames(styles.chevron)}
          />
        </RowGroup>
      </SequenceLoaderContext.Provider>
    ),

    [
      buildTypeInfoClasses,
      buildTypeId,
      name,
      pipelineId,
      isShowFavaoriteStar,
      hasContent,
      emptyText,
      description,
      isShowBuildTypePauseDropdown,
      isShowOverviewSystemProblems,
      branch,
      actionsContent,
      expanded,
    ],
  )
  useSequenceLoaderReadyHandler(!expanded)

  return (
    <Details
      label={name ?? ''}
      onToggle={toggleExpand}
      open={expanded}
      renderButtonAside
      level={2}
      imitateHeading
      summaryClassName={styles.button}
      headingClassName={summaryClass}
      detailsWrapperClassName={styles.details}
      detailsClassName={styles.details}
      summary={Summary}
    >
      {children}
    </Details>
  )
}

export default compose(
  connect(mapStateToProps, actionCreators),
  withHandlers({
    toggleExpand:
      ({
        pipelineId,
        buildTypeId,
        toggleBuildTypeExpand,
        togglePipelineExpand,
        expanded,
      }: ContainerOwnProps & ContainerStateProps & ContainerActionProps) =>
      () => {
        if (buildTypeId) {
          toggleBuildTypeExpand(buildTypeId, !expanded)
        } else if (pipelineId) {
          togglePipelineExpand(pipelineId, !expanded)
        }
      },
  }),
  React.memo,
  withOneLineProp,
  withBranchProps,
  React.memo,
)(BuildTypeLine)
